"use client";

import { useLayoutEffect, useRef, useState } from "react";
import "./phrase-handoff.css";

export interface PhraseHandoffProps {
  prefix: string;
  phrases: string[];
  suffix?: string;
  className?: string;
}

export function PhraseHandoff({
  prefix,
  phrases,
  suffix = "",
  className = "",
}: PhraseHandoffProps) {
  const options = phrases.map((phrase) => phrase.trim()).filter(Boolean);
  const [index, setIndex] = useState(0);
  const [direction, setDirection] = useState<"next" | "previous">("next");
  const phraseRef = useRef<HTMLSpanElement>(null);
  const animationRef = useRef<Animation | null>(null);

  const optionCount = Math.max(options.length, 1);
  const currentIndex = index % optionCount;
  const current = options[currentIndex] ?? "";
  const previousValue = useRef<string | null>(null);
  const sentence = [prefix, current, suffix].filter(Boolean).join(" ");

  useLayoutEffect(() => {
    const element = phraseRef.current;
    if (!element) return;
    if (previousValue.current === null) {
      previousValue.current = current;
      return;
    }
    if (previousValue.current === current) return;
    previousValue.current = current;

    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const running = animationRef.current;
    if (running) {
      try {
        running.commitStyles();
      } catch {
        // The animation may already be detached during rapid replacement.
      }
      running.cancel();
    }

    if (reducedMotion) {
      element.style.removeProperty("opacity");
      element.style.removeProperty("transform");
      animationRef.current = null;
      return;
    }

    const computed = getComputedStyle(element);
    const settled = computed.transform === "none" && computed.opacity === "1";
    const offset = direction === "next" ? "8px" : "-8px";
    const animation = element.animate(
      [
        {
          opacity: settled ? 0.45 : Number.parseFloat(computed.opacity),
          transform: settled ? `translateY(${offset})` : computed.transform,
        },
        { opacity: 1, transform: "translateY(0)" },
      ],
      {
        duration: 180,
        easing: "cubic-bezier(0.22, 1, 0.36, 1)",
        fill: "forwards",
      },
    );
    animationRef.current = animation;
    animation.onfinish = () => {
      if (animationRef.current !== animation) return;
      animation.cancel();
      element.style.removeProperty("opacity");
      element.style.removeProperty("transform");
      animationRef.current = null;
    };

    return () => {
      if (animationRef.current !== animation) return;
      try {
        animation.commitStyles();
      } catch {
        // Detached animations need no retained visual state.
      }
      animation.onfinish = null;
      animation.cancel();
      animationRef.current = null;
    };
  }, [current, direction]);

  if (options.length === 0) return null;

  function move(step: -1 | 1) {
    setDirection(step === 1 ? "next" : "previous");
    setIndex((current) => (current + step + options.length) % options.length);
  }

  return (
    <div className={`tb-phrase-handoff ${className}`.trim()}>
      <p className="tb-phrase-handoff__sr" aria-live="polite">
        {sentence}
      </p>
      <p className="tb-phrase-handoff__sentence" aria-hidden="true">
        <span>{prefix} </span>
        <span className="tb-phrase-handoff__slot">
          {options.map((option) => (
            <span className="tb-phrase-handoff__measure" key={option} aria-hidden="true">
              {option}
            </span>
          ))}
          <span
            className="tb-phrase-handoff__phrase"
            ref={phraseRef}
          >
            {current}
          </span>
        </span>
        {suffix ? <span> {suffix}</span> : null}
      </p>
      {options.length > 1 ? (
        <div className="tb-phrase-handoff__controls" role="group" aria-label="Phrase controls">
          <button type="button" onClick={() => move(-1)}>
            Previous
          </button>
          <span aria-hidden="true">
            {currentIndex + 1} / {options.length}
          </span>
          <button type="button" onClick={() => move(1)}>
            Next
          </button>
        </div>
      ) : null}
    </div>
  );
}

export default PhraseHandoff;

.tb-phrase-handoff {
  container-type: inline-size;
  display: grid;
  gap: clamp(28px, 7cqi, 64px);
  width: 100%;
  color: #f4f1e8;
}

.tb-phrase-handoff__sentence {
  max-width: 19ch;
  margin: 0;
  font: 620 clamp(2rem, 8cqi, 5.4rem) / 1 system-ui, sans-serif;
  letter-spacing: -0.055em;
}

.tb-phrase-handoff__slot {
  display: inline-grid;
  overflow: clip;
  margin-block: -0.14em;
  padding-block: 0.14em;
  vertical-align: -0.08em;
}

.tb-phrase-handoff__slot > span {
  grid-area: 1 / 1;
}

.tb-phrase-handoff__measure {
  visibility: hidden;
}

.tb-phrase-handoff__phrase {
  display: inline-block;
  color: #d4ff57;
}

.tb-phrase-handoff__controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  width: min(100%, 390px);
  font: 600 0.78rem / 1 system-ui, sans-serif;
}

.tb-phrase-handoff__controls button {
  min-height: 44px;
  padding: 0 2px;
  border: 0;
  border-bottom: 1px solid currentColor;
  border-radius: 0;
  color: inherit;
  background: transparent;
  font: inherit;
  cursor: pointer;
}

.tb-phrase-handoff__controls button:focus-visible {
  outline: 2px solid #d4ff57;
  outline-offset: 5px;
}

.tb-phrase-handoff__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  .tb-phrase-handoff__phrase {
    opacity: 1 !important;
    transform: none !important;
  }
}

@media (forced-colors: active) {
  .tb-phrase-handoff,
  .tb-phrase-handoff__phrase {
    color: CanvasText;
  }
}
